def check(a):
    n = 40
    d = 39 - a
    if d < 0: return False
    if d == 0: return True

    for k in range(n):
        for m in range(k + 1, n - k + 1):
            if m % 2 == (n - k) % 2:
                dp = [[float('inf')] * (n - k + 1) for _ in range(m + 1)]
                dp[0][0] = 0
                for i in range(1, m + 1):
                    for j in range(1, n - k + 1):
                        for ni in range(1, j + 1, 2):
                            val = max(d % 2, ni * (d - ni + 1))
                            if dp[i-1][j-ni] != float('inf'):
                                dp[i][j] = min(dp[i][j], dp[i-1][j-ni] + val)

                min_sum_E = min(dp[m][j] for j in range(n - k + 1))
                if min_sum_E <= k * (n - k):
                    return True
    return False

