def solve_large_n(n):
    # n is the number of teams
    for d in range(n - 1, -1, -1):
        for k in range(n):
            s_min = max(1, d - k + 1)
            if s_min % 2 == 0:
                s_min += 1

            for m in range(k + 2, n - k + 1):
                if m * s_min > n - k:
                    break

                for S in range(m * s_min, n - k + 1):
                    if S % 2 == (m * s_min) % 2:
                        s_last = S - (m - 1) * s_min
                        if s_last >= s_min and s_last % 2 == 1:
                            total = (d + 1) * S - ((m - 1) * s_min**2 + s_last**2)
                            if total <= d * k:
                                return d
    return -1

