                    break

                for S in range(m * s_min, n - k + 1):
                    if S % 2 == (m * s_min) % 2:
                        s_last = S - (m - 1) * s_min
                        if s_last >= s_min and s_last % 2 == 1:
                            # The condition sum s_i(d - s_i + 1) <= d * k
                            # is equivalent to (d+1)S - sum s_i^2 <= d * k.
                            # We maximize sum s_i^2 by taking s_i as unequal as possible.
                            sum_s_sq = (m - 1) * s_min**2 + s_last**2
                            if (d + 1) * S - sum_s_sq <= d * k:
                                return d
    return -1

